# typed: false
# frozen_string_literal: true

# Osy# — the local-first Osy# runtime and CLI. Generated by packaging/render-homebrew-formula.sh; do not edit by hand.
class Osy < Formula
  desc "Osy# local runtime and CLI (osy + osyrin)"
  homepage "https://osysharp.com"
  version "0.17.9"
  # Osyrin's licence terms: free to use, proprietary (card cli-licence-terms, owner 2026-10-19). Homebrew's license field takes
  # SPDX identifiers only, and :cannot_represent is its word for terms SPDX has no identifier for. The terms themselves are
  # LICENSE.txt, carried in the archive and installed into the prefix.
  license :cannot_represent

  # Apple silicon only: there is no Intel Mac build after 0.14.6 (owner, 2026-10-21), and Homebrew says so on an Intel Mac.
  on_macos do
    depends_on arch: :arm64
    url "https://github.com/osysharp/cli/releases/download/v0.17.9/osy-macos-arm64.tar.gz"
    sha256 "8850e0791ec64f6c4f75f668cf84c8084dfcf7aceb31d7918ed96db5e882742b"
  end

  on_linux do
    on_arm do
      url "https://github.com/osysharp/cli/releases/download/v0.17.9/osy-linux-arm64.tar.gz"
      sha256 "a238ba904c7c7714f94fef7beeae1b1bc59d019a23235288610b55b299034354"
    end
    on_intel do
      url "https://github.com/osysharp/cli/releases/download/v0.17.9/osy-linux-x64.tar.gz"
      sha256 "a6bd4238db0ed3ef28d3d6a5161c2f967ccf86f1210a8621fe8298ba889938b5"
    end
  end

  def install
    # The whole self-contained tree lives in libexec (the runtime dylibs and the .vsix must sit beside the apphost);
    # osy and osyrin are the only things on PATH.
    prefix.install "LICENSE.txt"
    libexec.install Dir["*"]
    bin.install_symlink libexec/"osy"
    bin.install_symlink libexec/"osyrin"
  end

  # Homebrew installs into its own prefix and may not write to your home directory, so the Claude Code skills for
  # Osyrin Cloud are one command away rather than installed here (the curl installer installs them itself).
  def caveats
    <<~EOS
      To give Claude Code the Osyrin Cloud skills (sign in, deploy, people, secrets, domains, backups, logs):
        osy skills install
    EOS
  end

  # `osy --help` exits 0, so the test that expected 1 failed every `brew test` (found 2026-10-19, publishing 0.14.2). The
  # version line is the receipt that the symlinked script found its binary and that it is THIS release.
  test do
    assert_match version.to_s, shell_output("#{bin}/osy --version")
    assert_match version.to_s, shell_output("#{bin}/osyrin --version")
  end
end
